# "Relative" — a fully procedural Blender Python animation about Speed.
# Everything (geometry, materials, motion, camera, HUD text) is generated by this script.
import bpy, math, random, sys, os
from mathutils import Vector, Color

argv = sys.argv[sys.argv.index("--")+1:] if "--" in sys.argv else []
MODE = argv[0] if argv else "all"          # all | test | wip
OUT = os.path.dirname(os.path.abspath(__file__))
random.seed(7)
FPS, F_END = 24, 288
F_TUNNEL_END, F_STOP = 168, 192
L = 520.0          # tunnel length
FINISH = L + 10.0

bpy.ops.wm.read_factory_settings(use_empty=True)
sc = bpy.context.scene
sc.render.fps = FPS; sc.frame_start = 1; sc.frame_end = F_END
sc.render.engine = 'CYCLES'
sc.cycles.device = 'CPU'
sc.cycles.samples = 20
sc.cycles.use_denoising = True
sc.cycles.max_bounces = 3
sc.render.resolution_x, sc.render.resolution_y = 1280, 720
sc.render.use_motion_blur = True
sc.render.motion_blur_shutter = 0.3
sc.view_settings.view_transform = 'AgX'
sc.view_settings.look = 'AgX - Punchy' if 'AgX - Punchy' in [i.identifier for i in sc.view_settings.bl_rna.properties['look'].enum_items] else 'None'

world = bpy.data.worlds.new("W"); sc.world = world; world.use_nodes = True
bg = world.node_tree.nodes["Background"]; bg.inputs[0].default_value = (0.004, 0.005, 0.012, 1); bg.inputs[1].default_value = 1

def emis(name, color, strength, use_obj_color=False):
    m = bpy.data.materials.new(name); m.use_nodes = True
    nt = m.node_tree; nt.nodes.clear()
    o = nt.nodes.new("ShaderNodeOutputMaterial"); e = nt.nodes.new("ShaderNodeEmission")
    e.inputs["Strength"].default_value = strength
    if use_obj_color:
        oi = nt.nodes.new("ShaderNodeObjectInfo"); nt.links.new(oi.outputs["Color"], e.inputs["Color"])
    else:
        e.inputs["Color"].default_value = (*color, 1)
    nt.links.new(e.outputs[0], o.inputs[0]); return m

def pbsdf(name, color, rough=0.5, metal=0.0, em=None, ems=0.0):
    m = bpy.data.materials.new(name); m.use_nodes = True
    p = m.node_tree.nodes["Principled BSDF"]
    p.inputs["Base Color"].default_value = (*color, 1)
    p.inputs["Roughness"].default_value = rough; p.inputs["Metallic"].default_value = metal
    if em:
        p.inputs["Emission Color"].default_value = (*em, 1); p.inputs["Emission Strength"].default_value = ems
    return m

def obj_from(op, **kw):
    op(**kw); return bpy.context.active_object

# ---------- motion profile ----------
def racer_y(f):
    if f <= F_TUNNEL_END:
        t = (f-1)/(F_TUNNEL_END-1); return L*(0.15*t + 0.85*t**4)
    if f <= F_STOP:
        t = (f-F_TUNNEL_END)/(F_STOP-F_TUNNEL_END)
        v0 = L*(0.15+3.4)/(F_TUNNEL_END-1)      # speed at tunnel exit (units/frame)
        d = FINISH-0.6-L                        # braking distance
        # cubic ease-out matching entry speed roughly, capped at distance d
        return L + d*(1-(1-t)**3)
    return FINISH-0.6
def racer_speed(f):
    return max(0.0, racer_y(f+0.5)-racer_y(f-0.5))   # units/frame

# ---------- tunnel rings ----------
ring_mesh = obj_from(bpy.ops.mesh.primitive_torus_add, major_radius=2.2, minor_radius=0.035, major_segments=48, minor_segments=6, rotation=(math.pi/2,0,0))
ring_mesh.name = "Ring_000"; ring_mat = emis("RingMat", None, 2.2, use_obj_color=True); ring_mesh.data.materials.append(ring_mat)
rings = [ring_mesh]
N = int(L/2.0)
for i in range(N):
    o = ring_mesh if i == 0 else ring_mesh.copy()
    if i: sc.collection.objects.link(o)
    o.location = (0, i*2.0, 0)
    h = 0.62 - 0.62*(i/N)       # blue -> red along the run
    c = Color(); c.hsv = (h, 1.0, 1.0); o.color = (c.r, c.g, c.b, 1)
    o.rotation_euler[1] = (i*0.09)  # slow twist (visible as torus seam variation)
# rectangular "rails" for parallax
rail_mat = emis("Rail", (0.9,0.95,1.0), 3)
for x,z in [(-1.6,-1.3),(1.6,-1.3)]:
    r = obj_from(bpy.ops.mesh.primitive_cube_add, size=1, location=(x, L/2, z)); r.scale = (0.03, L/2, 0.03); r.data.materials.append(rail_mat)

# streak particles
dust_mat = emis("Dust", (1,1,1), 6)
dust = obj_from(bpy.ops.mesh.primitive_cube_add, size=1); dust.scale=(0.015,0.25,0.015); dust.data.materials.append(dust_mat)
for i in range(700):
    o = dust if i == 0 else dust.copy()
    if i: sc.collection.objects.link(o)
    a = random.random()*math.tau; rr = random.uniform(2.6, 7)
    o.location = (math.cos(a)*rr, random.uniform(0, L+40), math.sin(a)*rr)

# ---------- racer ----------
racer = obj_from(bpy.ops.mesh.primitive_uv_sphere_add, radius=1, segments=32, ring_count=16)
racer.name="Racer"; racer.scale=(0.22,0.55,0.16)
bpy.ops.object.shade_smooth()
racer.data.materials.append(pbsdf("RacerMat",(0.04,0.045,0.06),0.18,0.9))
stripe_m = emis("Stripe",(1.0,0.3,0.03),12)
for sx in (-0.2,0.2):
    st_ = obj_from(bpy.ops.mesh.primitive_cube_add, size=1, location=(sx,0,0.02)); st_.scale=(0.02,0.75,0.02); st_.data.materials.append(stripe_m); st_.parent=racer
core = obj_from(bpy.ops.mesh.primitive_uv_sphere_add, radius=0.12, location=(0,0.15,0.13)); core.parent = racer
core.data.materials.append(emis("Cockpit",(0.5,0.9,1.0),15))
trail = obj_from(bpy.ops.mesh.primitive_cone_add, radius1=0.17, radius2=0.0, depth=1, rotation=(math.pi/2,0,0))
trail.data.materials.append(emis("Trail",(1.0,0.55,0.15),25)); trail.parent = racer
light = bpy.data.lights.new("RacerGlow", 'POINT'); light.energy = 60; light.color=(1,0.5,0.2)
lo = bpy.data.objects.new("RacerGlow", light); sc.collection.objects.link(lo); lo.parent = racer; lo.location=(0,0,0.6)

# ---------- finish area ----------
floor = obj_from(bpy.ops.mesh.primitive_plane_add, size=1, location=(0, FINISH+10, -0.18)); floor.scale=(30, 45, 1)
fm = bpy.data.materials.new("Floor"); fm.use_nodes=True; nt=fm.node_tree
p=nt.nodes["Principled BSDF"]; ch=nt.nodes.new("ShaderNodeTexChecker"); ch.inputs["Scale"].default_value=60
ch.inputs[1].default_value=(0.05,0.05,0.06,1); ch.inputs[2].default_value=(0.02,0.02,0.025,1)
nt.links.new(ch.outputs[0], p.inputs["Base Color"]); p.inputs["Roughness"].default_value=0.35
floor.data.materials.append(fm)
line = obj_from(bpy.ops.mesh.primitive_plane_add, size=1, location=(0, FINISH, -0.17)); line.scale=(4,0.6,1)
lm = bpy.data.materials.new("FinishLine"); lm.use_nodes=True; nt=lm.node_tree; nt.nodes.clear()
out=nt.nodes.new("ShaderNodeOutputMaterial"); em=nt.nodes.new("ShaderNodeEmission"); ck=nt.nodes.new("ShaderNodeTexChecker")
ck.inputs["Scale"].default_value=8; ck.inputs[1].default_value=(1,1,1,1); ck.inputs[2].default_value=(0,0,0,1)
nt.links.new(ck.outputs[0],em.inputs[0]); em.inputs[1].default_value=2; nt.links.new(em.outputs[0],out.inputs[0]); line.data.materials.append(lm)
key = bpy.data.lights.new("Key",'AREA'); key.energy=900; key.size=8
ko = bpy.data.objects.new("Key",key); sc.collection.objects.link(ko); ko.location=(4, FINISH-2, 7); ko.rotation_euler=(math.radians(35),math.radians(20),0)
rim = bpy.data.lights.new("Rim",'AREA'); rim.energy=500; rim.size=5; rim.color=(0.4,0.6,1)
ro = bpy.data.objects.new("Rim",rim); sc.collection.objects.link(ro); ro.location=(-3, FINISH+6, 3); ro.rotation_euler=(math.radians(-60),math.radians(-30),0)

# ---------- the snail (already across the line) ----------
snail_root = bpy.data.objects.new("Snail", None); sc.collection.objects.link(snail_root)
SY = FINISH + 1.6
snail_root.location = (0.9, SY, -0.18); snail_root.rotation_euler=(0,0,math.pi)
skin = pbsdf("SnailSkin",(0.55,0.75,0.45),0.35,0.0,(0.2,0.4,0.15),0.3)
shellm = pbsdf("Shell",(0.6,0.3,0.12),0.3,0.0)
body = obj_from(bpy.ops.mesh.primitive_uv_sphere_add, radius=1, segments=32, ring_count=16, location=(0,0.15,0.12)); body.scale=(0.22,0.75,0.13); bpy.ops.object.shade_smooth()
body.data.materials.append(skin); body.parent=snail_root
head = obj_from(bpy.ops.mesh.primitive_uv_sphere_add, radius=0.17, location=(0,0.78,0.22)); bpy.ops.object.shade_smooth(); head.data.materials.append(skin); head.parent=snail_root
shell = obj_from(bpy.ops.mesh.primitive_uv_sphere_add, radius=0.42, segments=32, ring_count=16, location=(0,-0.1,0.5)); shell.scale=(0.75,1,1); bpy.ops.object.shade_smooth(); shell.data.materials.append(shellm); shell.parent=snail_root
# spiral on the shell side (procedural curve)
cu = bpy.data.curves.new("Spiral",'CURVE'); cu.dimensions='3D'; cu.bevel_depth=0.022
sp = cu.splines.new('POLY'); pts=[]
for k in range(120):
    a = k*0.14; r = 0.37*(1-k/120)
    pts.append((0.33, -0.1+math.cos(a)*r, 0.5+math.sin(a)*r))
sp.points.add(len(pts)-1)
for pt,(x,y,z) in zip(sp.points,pts): pt.co=(x,y,z,1)
spo = bpy.data.objects.new("Spiral",cu); sc.collection.objects.link(spo); cu.materials.append(pbsdf("SpiralMat",(0.25,0.1,0.04),0.4)); spo.parent=snail_root
eyes=[]
for sx in (-0.07,0.07):
    st = obj_from(bpy.ops.mesh.primitive_cylinder_add, radius=0.018, depth=0.3, location=(sx,0.85,0.42), rotation=(math.radians(-15),math.radians(sx*120),0)); st.data.materials.append(skin); st.parent=snail_root
    eb = obj_from(bpy.ops.mesh.primitive_uv_sphere_add, radius=0.05, location=(sx*1.5,0.89,0.57)); eb.data.materials.append(pbsdf("EyeW",(1,1,1),0.2)); eb.parent=snail_root
    pu = obj_from(bpy.ops.mesh.primitive_uv_sphere_add, radius=0.025, location=(sx*1.5,0.935,0.58)); pu.data.materials.append(pbsdf("Pupil",(0,0,0),0.1)); pu.parent=snail_root
    eyes.append(pu)
# tiny trophy
cup = obj_from(bpy.ops.mesh.primitive_cone_add, radius1=0.05, radius2=0.11, depth=0.16, location=(0,-0.1,1.02)); cup.data.materials.append(pbsdf("Gold",(1,0.75,0.2),0.15,1.0)); cup.parent=snail_root
cupbase = obj_from(bpy.ops.mesh.primitive_cylinder_add, radius=0.06, depth=0.04, location=(0,-0.1,0.93)); cupbase.data.materials.append(bpy.data.materials["Gold"]); cupbase.parent=snail_root
# snail creeps forward 0.25 units over the whole ending
for f in (F_STOP, F_END):
    snail_root.location.y = SY + (0 if f==F_STOP else -0.25); snail_root.keyframe_insert("location", frame=f)
# pupils look at racer once it stops (keyframed)
for pu in eyes:
    pu.keyframe_insert("location", frame=F_STOP+12)
    pu.location.x += 0.02; pu.keyframe_insert("location", frame=F_STOP+20)

# ---------- camera ----------
cam_d = bpy.data.cameras.new("Cam"); cam = bpy.data.objects.new("Cam", cam_d); sc.collection.objects.link(cam); sc.camera = cam
cam_d.clip_end = 2000

# ---------- text ----------
txt_mat = emis("Txt",(1,1,1),3)
def text(body, size, loc, parent=None, align='CENTER'):
    cu = bpy.data.curves.new("T",'FONT'); cu.body=body; cu.size=size; cu.align_x=align; cu.align_y='CENTER'
    o = bpy.data.objects.new("T",cu); sc.collection.objects.link(o); o.location=loc; cu.materials.append(txt_mat)
    if parent: o.parent=parent
    return o
hud = text("0 km/h", 0.06, (0.0,-0.22,-1), parent=cam)
caption1 = text("SPEED = DISTANCE / TIME", 0.05, (0,0.19,-1), parent=cam)
caption2 = text("the snail just left earlier.", 0.035, (0,0.13,-1), parent=cam)
def vis(o, ranges):
    for f in range(1, F_END+1):
        on = any(a<=f<=b for a,b in ranges)
        o.hide_render = not on; o.hide_viewport = not on
        o.keyframe_insert("hide_render", frame=f); o.keyframe_insert("hide_viewport", frame=f)
    for fc in (o.animation_data.action.fcurves if hasattr(o.animation_data.action,'fcurves') else []):
        for kp in fc.keyframe_points: kp.interpolation='CONSTANT'
vis(hud, [(1, F_STOP+6)]); vis(caption1, [(236, F_END)]); vis(caption2, [(252, F_END)])

def kmh(f):
    # map the racer's speed exponentially onto 0 -> 1.08e9 km/h (speed of light)
    v = racer_speed(f); vmax = racer_speed(F_TUNNEL_END)
    x = min(1.0, v/vmax)
    return 0 if v < 1e-4 else int(10**(1 + 8.03*x**1.4))

def ease(t): return t*t*(3-2*t)
# keyframe racer, trail, camera per frame
for f in range(1, F_END+1):
    y = racer_y(f); v = racer_speed(f)
    racer.location = (0, y, 0); racer.keyframe_insert("location", frame=f)
    # tiny vibration that grows with speed
    racer.rotation_euler = (0, math.sin(f*1.7)*0.02*min(1, v/4), 0); racer.keyframe_insert("rotation_euler", frame=f)
    trail.scale = (1, 0.2 + v*0.35, 1); trail.location = (0, -0.55 - (0.2+v*0.35)/2, 0)
    trail.keyframe_insert("scale", frame=f); trail.keyframe_insert("location", frame=f)
    if f <= F_TUNNEL_END + 6:
        shake = 0.012*min(1, v/3)
        cam.location = (0.0+math.sin(f*2.3)*shake, y-3.4-min(v*0.05,1.2), 0.75+math.cos(f*3.1)*shake)
        cam.rotation_euler = (math.radians(84), 0, 0)
        cam_d.lens = 32 - 18*min(1, v/racer_speed(F_TUNNEL_END))
    else:
        t = ease(min(1, (f-(F_TUNNEL_END+6))/40))
        a = Vector((0.0, y-3.4, 0.75)); b = Vector((3.4, FINISH-2.2, 1.3))
        cam.location = a.lerp(b, t)
        target = Vector((0.4, FINISH+0.6, 0.25))
        d = (target - cam.location); rot = d.to_track_quat('-Z','Y').to_euler()
        cam.rotation_euler = rot
        cam_d.lens = 14 + (35-14)*t
    cam.keyframe_insert("location", frame=f); cam.keyframe_insert("rotation_euler", frame=f); cam_d.keyframe_insert("lens", frame=f)

def render_frame(f, path):
    sc.frame_set(f)
    hud.data.body = f"{kmh(f):,} km/h"
    sc.render.filepath = path
    bpy.ops.render.render(write_still=True)

if MODE == "test":
    sc.cycles.samples = 12
    for f in map(int, argv[1:]): render_frame(f, f"{OUT}/test_{f:04d}.png")
elif MODE == "wip":
    bpy.ops.wm.save_as_mainfile(filepath=f"{OUT}/wip/relative.blend")
else:
    start = int(argv[1]) if len(argv)>1 else 1; step = int(argv[2]) if len(argv)>2 else 1
    for f in range(start, F_END+1, step):
        p = f"{OUT}/frames/{f:04d}.png"
        if os.path.exists(p): continue
        render_frame(f, p)
